{"command": "cd /Users/michelkerkmeester/worktrees/public/315-frontend-reference-restructure && python3 - <<'PY'
import subprocess, re, sys
files = [
 ".skilled/skills/sk-code/README.md",
 ".skilled/skills/sk-code/ROUTER.md",
 ".skilled/skills/sk-code/SKILL.md",
 ".skilled/skills/sk-code/shared/README.md",
 ".skilled/skills/sk-code/shared/references/phase-detection.md",
 ".skilled/skills/sk-code/shared/references/stack-detection.md",
 ".skilled/skills/sk-code/shared/references/universal/code-quality-standards.md",
 ".skilled/skills/sk-code/shared/references/universal/rule-overrides.md",
 ".skilled/skills/sk-code/shared/references/workflow-debug.md",
 ".skilled/skills/sk-code/shared/references/workflow-implement.md",
 ".skilled/skills/sk-code/shared/references/workflow-verify.md",
]
def blocks(text):
    out=[]; cur=None; buf=[]
    for line in text.splitlines():
        m=re.match(r'^(\s*)(`{3,}|~{3,})(.*)$', line)
        if cur is None and m:
            cur=(m.group(2), m.group(3)); buf=[line]; continue
        if cur is not None:
            buf.append(line)
            if re.match(r'^\s*'+re.escape(cur[0][0])+'{%d,}\s*$'%len(cur[0]), line):
                out.append("\n".join(buf)); cur=None; buf=[]
    return out
for f in files:
    head=subprocess.run(["git","show","HEAD:"+f],capture_output=True,text=True).stdout
    now=open(f).read()
    a,b=blocks(head),blocks(now)
    if a!=b:
        print("DIFF", f, len(a), len(b))
        for i,(x,y) in enumerate(zip(a,b)):
            if x!=y: print("  block",i,"differs")
        if len(a)!=len(b): print("  count mismatch")
print("done")
PY"}

