6: // A mode's config file lives inside the skill folder, so the same file travels with the
7: // skill into every repository that installs it. Its `repository` field names the one
8: // repository the file was written for, and a caller checks that field against the
9: // repository it is actually running in before it trusts the rest of the file.
10: //
11: // WHY THIS EXISTS: without the check, a config copied into a second repository would
12: // silently apply the first repository's conventions there. The identity is read from
13: // the environment first, because CI sets the canonical `owner/name`, and from the origin
14: // remote otherwise, because a local clone has no such variable. Both paths go through one
15: // parser, so a value from either source is compared in the same spelling, and neither a
16: // missing remote nor a malformed URL throws: an unknown repository is a normal answer,
17: // not a failure of the run.
18: 
19: // ─────────────────────────────────────────────────────────────────────────────
20: // 1. IMPORTS
21: // ─────────────────────────────────────────────────────────────────────────────
22: 
23: const { spawnSync } = require('node:child_process');
24: 
25: // ─────────────────────────────────────────────────────────────────────────────
26: // 2. CONSTANTS
27: // ─────────────────────────────────────────────────────────────────────────────
28: 
29: const REPOSITORY_PATTERN = /^[A-Za-z0-9._-]+\/[A-Za-z0-9._-]+$/;
30: // git accepts the scp-like `[user@]host:path`, where a remote named in an ssh config needs
31: // no user, so the host is whatever sits before the first colon that does not open a
32: // `//` URL.
33: const SCP_LIKE = /^(?:[^@\s/]+@)?([^:/\s]+):(?!\/\/)(.+)$/;
34: // A drive-letter path is a local path. Without this check the scp-like form would read it
35: // as a host and a path, and `C:/work/owner/name` would answer as `owner/name`.
36: const WINDOWS_DRIVE = /^[A-Za-z]:[\\/]/;
37: const GIT_TIMEOUT_MS = 5000;
38: 
39: // ─────────────────────────────────────────────────────────────────────────────
40: // 3. HELPERS
41: // ─────────────────────────────────────────────────────────────────────────────
42: 
43: // The path part of a URL, for both `scheme://host/path` and the scp-like
44: // `[user@]host:path` form git also accepts. Returns null when neither shape fits.
45: function remotePath(text) {
46:   if (text.includes('://')) {
47:     try {
48:       return new URL(text).pathname;
49:     } catch {
50:       return null;
51:     }
52:   }
53:   if (WINDOWS_DRIVE.test(text)) return null;
54:   const match = SCP_LIKE.exec(text);
55:   return match ? match[2] : null;
56: }
57: 
58: // ─────────────────────────────────────────────────────────────────────────────
59: // 4. CORE LOGIC
60: // ─────────────────────────────────────────────────────────────────────────────
61: 
62: /**
63:  * Reduce a git remote URL to its `owner/name` identity.
64:  *
65:  * @param {string} url - An https, ssh or scp-like remote URL, with or without a user.
66:  * @returns {string|null} The identity, or null when the text names no repository.
67:  */
68: function normalizeRemote(url) {
69:   if (typeof url !== 'string') return null;
70:   const text = url.trim();
71:   if (text === '') return null;
72: 
73:   const pathPart = remotePath(text);
74:   if (pathPart === null) return null;
75: 
76:   const segments = pathPart.split('/').filter(Boolean);
77:   if (segments.length < 2) return null;
78: 
79:   const owner = segments[segments.length - 2];
80:   const name = segments[segments.length - 1].replace(/\.git$/i, '');
81:   const identity = `${owner}/${name}`;
82:   return REPOSITORY_PATTERN.test(identity) ? identity : null;
83: }
84: 
85: /**
86:  * Read the repository the given working tree belongs to.
87:  *
88:  * @param {Object} [options] - root of the working tree and the environment to read.
89:  * @returns {{identity: string|null, source: 'env'|'origin'|null}}
90:  */
91: function currentRepository({ root = process.cwd(), env = process.env } = {}) {
92:   const declared = typeof env.GITHUB_REPOSITORY === 'string' ? env.GITHUB_REPOSITORY.trim() : '';
93:   if (REPOSITORY_PATTERN.test(declared)) return { identity: declared, source: 'env' };
94: 
95:   let identity = null;
96:   try {
97:     const run = spawnSync('git', ['-C', root, '-c', 'core.fsmonitor=false', 'remote', 'get-url', 'origin'], {
98:       encoding: 'utf8',
99:       // The caller's environment decides which git configuration, and so which origin
100:       // remote, this read sees, so it has to reach the child as well.
101:       env,
102:       timeout: GIT_TIMEOUT_MS,
103:     });
104:     if (run.status === 0 && typeof run.stdout === 'string') identity = normalizeRemote(run.stdout);
105:   } catch {
106:     identity = null;
107:   }
108: 
109:   return identity === null ? { identity: null, source: null } : { identity, source: 'origin' };
110: }
111: 
112: /**
113:  * Whether a config file's declared repository applies to the current one.
114:  *
115:  * @param {string|null|undefined} declared - The file's `repository` field.
116:  * @param {string|null} current - The identity read from the working tree.
117:  * @returns {boolean} True for an absent field, or for the same identity in any case.
118:  */
119: function repositoryMatches(declared, current) {
120:   if (declared === undefined || declared === null) return true;
121:   if (typeof declared !== 'string' || typeof current !== 'string') return false;
122:   return declared.trim().toLowerCase() === current.trim().toLowerCase();
123: }
124: 
125: // ─────────────────────────────────────────────────────────────────────────────
126: // 5. EXPORTS
127: // ─────────────────────────────────────────────────────────────────────────────
128: 
129: module.exports = { REPOSITORY_PATTERN, currentRepository, normalizeRemote, repositoryMatches };

